from __future__ import absolute_import

import os

from kore import constant

CURRENT_PATH = os.path.dirname(__file__)


def getIconPath():
    return os.path.join(CURRENT_PATH, "icons")


def getIconFilepath(name):
    iconPath = getIconPath()

    filepath = os.path.abspath(os.path.join(iconPath, "%s.png" % name))
    return filepath.replace("\\", "/")


def getOrbitPath():
    warehousePath = os.path.abspath(
        os.path.join(os.environ["USERPROFILE"], "Documents", constant.TOOL_NAME)
    ).replace("\\", "/")

    if not os.path.isdir(warehousePath):
        os.makedirs(warehousePath)

    return warehousePath.replace("\\", "/")


def getPresetsPath():
    orbitPath = getOrbitPath()
    return os.path.abspath(os.path.join(orbitPath, "presets")).replace("\\", "/")


def getProjectPresetsPath():
    return os.path.abspath(os.path.join(getPresetsPath(), constant.PROJECT_PRESET_NAME)).replace(
        "\\", "/"
    )


def getCodePath():
    return os.path.join(CURRENT_PATH, "codes")


